const b = $('Start').first().json || {};

function normalizza(s) {
  if (!s) return '';
  return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/\s+/g, ' ').trim();
}

// I chiamanti passano i campi come stringhe: un valore assente arriva come
// '' (o 'null'), non come null. Senza questa normalizzazione max='' diventava
// Number('') = 0 e il filtro scartava ogni movimento.
const txt = v => (v === null || v === undefined || v === 'null' || v === 'undefined')
  ? '' : String(v).trim();
const num = v => {
  const t = txt(v);
  return t !== '' && Number.isFinite(Number(t)) ? Number(t) : null;
};

const q = normalizza(txt(b.q));
const parole = q ? q.split(' ').filter(Boolean) : [];
const da = txt(b.da), a = txt(b.a);
const categoria = txt(b.categoria), tipo = txt(b.tipo);
const min = num(b.min), max = num(b.max);

const tutte = [
  ...$('Leggi Transazioni4').all().map(i => i.json),];

const arr = n => Math.round(n * 100) / 100;

const trovati = tutte.filter(r => {
  const d = String(r.data_evento).slice(0, 10);
  if (da && d < da) return false;
  if (a && d > a) return false;
  if (categoria && String(r.categoria) !== categoria) return false;
  if (tipo && String(r.tipo) !== tipo) return false;
  const imp = Number(r.importo) || 0;
  if (min !== null && imp < min) return false;
  if (max !== null && imp > max) return false;
  if (!parole.length) return true;

  // Tutte le parole devono comparire da qualche parte: cercando
  // "bar michele" non voglio tutti i bar.
  const testo = normalizza([r.esercente, r.note, r.categoria, r.conto].join(' '));
  return parole.every(p => testo.includes(p));
});

const perCat = {};
let totale = 0;
for (const r of trovati) {
  if (String(r.tipo) !== 'spesa') continue;
  const imp = Number(r.importo) || 0;
  totale += imp;
  const c = String(r.categoria || 'Senza categoria');
  perCat[c] = (perCat[c] || 0) + imp;
}

const limite = Math.min(num(b.limite) || 100, 300);

return [{ json: {
  totale: arr(totale),
  conteggio: trovati.length,
  per_categoria: Object.keys(perCat)
    .map(nome => ({ nome, totale: arr(perCat[nome]) }))
    .sort((x, y) => y.totale - x.totale),
  movimenti: trovati
    .sort((x, y) => String(y.data_evento).localeCompare(String(x.data_evento)))
    .slice(0, limite)
    .map(r => ({
      hash: String(r.hash_dedup || ''),
      data: String(r.data_evento),
      importo: Number(r.importo) || 0,
      tipo: String(r.tipo || 'spesa'),
      etichetta: String(r.esercente || r.note || ''),
      categoria: String(r.categoria || ''),
      conto: String(r.conto || ''),
      fonte: String(r.fonte || ''),
      stato: String(r.stato || ''),
    })),
}}];
